head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > displaymessage]<br/>입력값에 대한 유효성 체크를 통과하지 못한 경우 실패 메시지의 출력 여부를 설정합니다.",
    "validation" : [
        "validate() 메소드로 입력값에 대한 유효성 체크를 수행합니다.",
        "미설정 시 유효성 체크를 통과하지 못해도 실패 메시지를 출력하지 않습니다. (기본값 false)",
        "true 설정 시 유효성 체크를 통과하지 못한 경우 실패 메시지를 출력합니다.",
        "true 설정 시 invalidMessage 속성으로 설정한 메시지가 출력됩니다.",
        "true 설정 시 invalidMessage 와 invalidMessageFunc 속성을 모두 설정하지 않으면 엔진 내부에 정의된 기본 메시지가 표시됩니다.",
        "false 설정 시 유효성 체크를 통과하지 못해도 실패 메시지를 출력하지 않습니다.",
        "실패 메시지는 alert() 메소드로 출력됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};


scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}


// target1 (displaymessage 미설정 / mandatory=true → validate 실패 시 alert 미출력)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("");
};

scwin.btn_validate1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validate(target1);
}


// target2 (displaymessage=true, invalidMessage 설정 / mandatory=true → 사용자 정의 메시지 alert)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("");
};

scwin.btn_validate2_onclick = function (e) {
    scwin.btn_setValue2_onclick();
    scwin.check_validate(target2);
}


// target3 (displaymessage=false, invalidMessage 설정 / mandatory=true → alert 미출력)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("");
};

scwin.btn_validate3_onclick = function (e) {
    scwin.btn_setValue3_onclick();
    scwin.check_validate(target3);
}


// target4 (displaymessage=true, invalidMessage/invalidMessageFunc 미설정 / mandatory=true → 엔진 기본 메시지 alert)
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("");
};

scwin.btn_validate4_onclick = function (e) {
    scwin.btn_setValue4_onclick();
    scwin.check_validate(target4);
}
